"use client";

import React, { useEffect, useLayoutEffect, useRef } from "react";
import { cn } from "@/lib/utils";
import { createSpringFollower } from "./motion-curves";

// Scroll choreography: wheel and touch input move a raw 0 → 1 progress, and
// the painted progress chases it through this smooth, damped spring stepped
// on requestAnimationFrame for a buttery, cinematic feel.
const PROGRESS_SPRING = { stiffness: 70, damping: 18, mass: 1.2, restDelta: 0.0004, restSpeed: 0.004 };

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type SplitCard = {
  title: string;
  description: string;
  bgColor?: string;
  backgroundColor?: string;
  textColor?: string;
  kicker?: string;
  tag?: string;
  number?: string;
  metric?: string;
  metricLabel?: string;
  location?: string;
};

export type SplitCardItem = SplitCard;

export interface ScrollSplitCardsProps
  extends React.HTMLAttributes<HTMLDivElement> {
  variant?: "default" | "slow-transition";
  items?: SplitCard[];
  cards?: SplitCard[];
  imageSrc?: string;
  imageUrl?: string;
  headerTitle?: string;
  headerSubtitle?: string;
  containerHeight?: string;
  enableScrollIndicator?: boolean;
  scrollSpeed?: number | "slow" | "normal" | "fast";
  speed?: number | "slow" | "normal" | "fast";
}

// ============================================================================
// DEFAULT DATA (Lago di Braies / Dolomite Alpine Lake Sanctuary)
// ============================================================================
export const DEFAULT_IMAGE =
  "https://res.cloudinary.com/dodndg7ai/image/upload/f_webp,q_auto/v1790224415/photo-1501785888041-af3ef285b470-1790146212207-1790224416318.jpg";

const DEFAULT_CARDS: SplitCard[] = [
  {
    title: "Lago di Braies",
    kicker: "SANCTUARY",
    metric: "1,496 M",
    metricLabel: "ELEVATION",
    location: "South Tyrol, Italy",
    description:
      "Glacial emerald waters mirror sheer limestone walls in the silent morning mist before rowers set out.",
    bgColor: "#13352F",
    textColor: "#E6F4F1",
  },
  {
    title: "The Boathouse",
    kicker: "HERITAGE",
    metric: "100+ YRS",
    metricLabel: "ROWBOAT CRAFT",
    location: "Prags Alpine Dock",
    description:
      "Handcrafted wooden larch skiffs moored to stilted pine docks, awaiting the gentle morning row across crystal shallows.",
    bgColor: "#A45229",
    textColor: "#FFF8F5",
  },
  {
    title: "Seekofel Peak",
    kicker: "UNESCO",
    metric: "2,810 M",
    metricLabel: "SUMMIT HEIGHT",
    location: "Dolomites Park",
    description:
      "Towering pale crags catch the first golden alpine glow, standing sentinel over the emerald basin below.",
    bgColor: "#141E2B",
    textColor: "#ECF3F9",
  },
];

// ============================================================================
// MATHEMATICAL EASING & CHOREOGRAPHY
// ============================================================================
function clamp01(n: number) {
  return Math.min(1, Math.max(0, n));
}

function remap(progress: number, from: number, to: number) {
  if (to === from) return progress >= to ? 1 : 0;
  return clamp01((progress - from) / (to - from));
}

function lerp(a: number, b: number, t: number) {
  return a + (b - a) * t;
}

/** Left/right panels shift outward, keeping a smaller peak and restGap on small screens to prevent clipping. */
function panelShiftX(progress: number, index: number, isSmall = false) {
  const dir = index === 0 ? -1 : index === 2 ? 1 : 0;
  const out = remap(progress, 0, 0.45);
  const settle = remap(progress, 0.45, 0.88);
  const peak = isSmall ? 18 : 48;
  return dir * lerp(0, peak, out) * (1 - settle * 0.45) || 0;
}

function panelRotateY(progress: number) {
  return lerp(0, 180, remap(progress, 0.35, 0.85));
}

function panelScale(progress: number, isSmall = false) {
  const target = isSmall ? 0.88 : 0.94;
  return lerp(1, target, remap(progress, 0, 0.38));
}

function panelRadius(progress: number, index: number) {
  const inner = lerp(0, 16, remap(progress, 0, 0.25));
  if (index === 0) return `16px ${inner}px ${inner}px 16px`;
  if (index === 2) return `${inner}px 16px 16px ${inner}px`;
  return `${inner}px`;
}

// ============================================================================
// PANEL COMPONENT (Refined Editorial Card Design with Visual Balance)
// ============================================================================
function Panel({
  card,
  index,
  imageSrc,
}: {
  card: SplitCard;
  index: number;
  imageSrc: string;
}) {
  // The resting (progress 0) radius. The scroll loop rewrites it, along with
  // the panel's transform, straight on the DOM every frame.
  const radius = panelRadius(0, index);

  const bgColor = card.bgColor || card.backgroundColor || "#13352F";
  const textColor = card.textColor || "#E6F4F1";
  const kicker = card.kicker || card.tag || "CHAPTER";
  const num = card.number || String(index + 1).padStart(2, "0");

  return (
    <div
      data-split-panel={index}
      className={cn(
        "relative h-full min-w-0 flex-[1_1_0] [transform-style:preserve-3d]",
        index > 0 ? "-ml-px" : ""
      )}
      style={{ zIndex: index }}
    >
      {/* Front Face: 1/3 of the seamless panoramic photograph */}
      <div
        data-split-face=""
        className="absolute inset-0 overflow-hidden [backface-visibility:hidden]"
        style={{ borderRadius: radius }}
      >
        <div
          className="absolute inset-0 h-full w-[300%]"
          style={{
            left: `${-100 * index}%`,
            backgroundImage: `url(${imageSrc})`,
            backgroundSize: "100% 100%",
            backgroundPosition: "center",
          }}
        />
      </div>

      {/* Back Face: Physical card reverse with rich editorial layout */}
      <div
        data-split-face=""
        className="absolute inset-0 flex flex-col justify-between overflow-hidden p-3 sm:p-5 md:p-7 antialiased [backface-visibility:hidden] select-none border border-white/10"
        style={{
          backgroundColor: bgColor,
          color: textColor,
          borderRadius: radius,
          transform: "rotateY(180deg)",
          boxShadow: "inset 0 1px 0 rgba(255,255,255,0.18)",
        }}
      >
        {/* Top Header Row: Category Badge & Numeric Index */}
        <div className="flex items-center justify-between gap-1">
          <div className="inline-flex items-center gap-1 sm:gap-1.5 px-1.5 sm:px-2.5 py-0.5 sm:py-1 rounded-full bg-white/10 backdrop-blur-sm border border-white/10 max-w-[78%]">
            <span className="size-1 sm:size-1.5 shrink-0 rounded-full bg-current opacity-80" />
            <span className="font-mono text-[7px] sm:text-[9px] md:text-[10px] font-semibold uppercase tracking-wider truncate">
              {kicker}
            </span>
          </div>
          <span className="font-mono text-[9px] sm:text-[11px] md:text-[12px] font-bold tabular-nums opacity-60 shrink-0">
            {num}
          </span>
        </div>

        {/* Mid Section: Feature Metric / Stat Badge */}
        <div className="my-auto py-1 sm:py-2">
          {card.metric ? (
            <div className="inline-flex flex-col">
              <span className="font-mono text-[7px] sm:text-[8.5px] md:text-[10px] uppercase tracking-wider opacity-60">
                {card.metricLabel || "METRIC"}
              </span>
              <span className="text-base sm:text-xl md:text-3xl font-extrabold tracking-tight mt-0.5">
                {card.metric}
              </span>
            </div>
          ) : (
            <div className="w-5 sm:w-6 h-[1.5px] opacity-30 bg-current" />
          )}
        </div>

        {/* Bottom Section: Display Title, Narrative & Location Footer */}
        <div>
          <h3 className="text-[13px] sm:text-[18px] md:text-[23px] font-bold tracking-tight leading-[1.15] text-balance">
            {card.title}
          </h3>
          <p className="mt-1 sm:mt-2 text-[9px] sm:text-[11.5px] md:text-[13px] leading-snug sm:leading-relaxed text-pretty opacity-85 line-clamp-2 sm:line-clamp-3 md:line-clamp-none">
            {card.description}
          </p>

          <div className="mt-2 sm:mt-3 pt-1.5 sm:pt-2.5 border-t border-current/15 flex items-center justify-between text-[7.5px] sm:text-[9.5px] md:text-[11px] font-mono uppercase tracking-wider opacity-75">
            <span className="truncate pr-1">{card.location || "Dolomites, Italy"}</span>
            <span className="text-[10px] sm:text-xs shrink-0">↗</span>
          </div>
        </div>
      </div>
    </div>
  );
}

// ============================================================================
// MAIN COMPONENT
// ============================================================================
export function ScrollSplitCards({
  variant = "default",
  items,
  cards,
  imageSrc,
  imageUrl,
  headerTitle = "Explore",
  headerSubtitle = "Scroll down to reveal the alpine lake narrative",
  containerHeight,
  enableScrollIndicator = true,
  scrollSpeed,
  speed,
  className = "",
  style,
  ...props
}: ScrollSplitCardsProps) {
  const cardList = (items || cards || DEFAULT_CARDS).slice(0, 3);
  const activeImage = imageSrc || imageUrl || DEFAULT_IMAGE;
  const defaultSpeedForVariant = variant === "slow-transition" ? "slow" : 1;
  const activeSpeed = speed ?? scrollSpeed ?? defaultSpeedForVariant;
  const speedFactor =
    typeof activeSpeed === "number"
      ? activeSpeed
      : activeSpeed === "slow"
      ? 0.5
      : activeSpeed === "fast"
      ? 1.8
      : 1;

  const containerRef = useRef<HTMLDivElement>(null);
  const headerRef = useRef<HTMLDivElement>(null);
  const stageRef = useRef<HTMLDivElement>(null);
  /** Repaints the current progress; set while the scroll loop is running. */
  const repaint = useRef<(() => void) | null>(null);

  // One loop owns the whole choreography: wheel / touch input moves the raw
  // progress, a spring follower smooths it, and every frame paints the stage,
  // header and panels from the smoothed value. The small-screen flag lives
  // here too, so a resize across the breakpoint just repaints.
  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    let isSmall = false;
    let raw = 0;

    const paint = (p: number) => {
      const stage = stageRef.current;
      const header = headerRef.current;

      if (stage) {
        const scale = panelScale(p, isSmall);
        stage.style.transform = scale !== 1 ? `scale(${scale})` : "none";
        stage.querySelectorAll<HTMLElement>("[data-split-panel]").forEach((panel) => {
          const index = Number(panel.dataset.splitPanel);
          const x = panelShiftX(p, index, isSmall);
          const rotateY = panelRotateY(p);
          const parts: string[] = [];
          if (x !== 0) parts.push(`translateX(${x}px)`);
          if (rotateY !== 0) parts.push(`rotateY(${rotateY}deg)`);
          panel.style.transform = parts.length ? parts.join(" ") : "none";
          const radius = panelRadius(p, index);
          panel.querySelectorAll<HTMLElement>("[data-split-face]").forEach((face) => {
            face.style.borderRadius = radius;
          });
        });
      }

      if (header) {
        // Opacity 1 → 0.8 → 0 over [0, 0.15, 0.28]; lift 0 → -18px over [0, 0.28].
        const opacity = p <= 0.15 ? lerp(1, 0.8, remap(p, 0, 0.15)) : lerp(0.8, 0, remap(p, 0.15, 0.28));
        const y = lerp(0, -18, remap(p, 0, 0.28));
        header.style.opacity = String(opacity);
        header.style.transform = y !== 0 ? `translateY(${y}px)` : "none";
      }
    };

    const spring = createSpringFollower(0, paint, PROGRESS_SPRING);
    repaint.current = () => paint(spring.get());

    const reducedMotion = () =>
      window.matchMedia?.("(prefers-reduced-motion: reduce)").matches === true;

    const moveTo = (next: number) => {
      raw = next;
      // Reduced motion: the panels track the input directly, with no spring
      // carrying them on after the wheel or finger stops.
      if (reducedMotion()) spring.jump(next);
      else spring.set(next);
    };

    const checkSize = (width: number) => {
      const small = width > 0 && width < 640;
      if (small !== isSmall) {
        isSmall = small;
        paint(spring.get());
      }
    };

    checkSize(el.clientWidth);
    const observer = new ResizeObserver((entries) => {
      for (const entry of entries) checkSize(entry.contentRect.width);
    });
    observer.observe(el);

    // Capture wheel and touch gestures on container so everything happens in-place
    const handleWheel = (e: WheelEvent) => {
      const current = raw;
      if ((e.deltaY > 0 && current < 1) || (e.deltaY < 0 && current > 0)) {
        e.preventDefault();
        const delta = e.deltaY * 0.00065 * speedFactor;
        moveTo(Math.min(Math.max(current + delta, 0), 1));
      }
    };

    let touchStartY = 0;
    const handleTouchStart = (e: TouchEvent) => {
      touchStartY = e.touches[0].clientY;
    };
    const handleTouchMove = (e: TouchEvent) => {
      const currentY = e.touches[0].clientY;
      const deltaY = touchStartY - currentY;
      touchStartY = currentY;
      const current = raw;
      if ((deltaY > 0 && current < 1) || (deltaY < 0 && current > 0)) {
        if (e.cancelable) e.preventDefault();
        moveTo(Math.min(Math.max(current + deltaY * 0.0012 * speedFactor, 0), 1));
      }
    };

    el.addEventListener("wheel", handleWheel, { passive: false });
    el.addEventListener("touchstart", handleTouchStart, { passive: true });
    el.addEventListener("touchmove", handleTouchMove, { passive: false });

    return () => {
      observer.disconnect();
      spring.destroy();
      repaint.current = null;
      el.removeEventListener("wheel", handleWheel);
      el.removeEventListener("touchstart", handleTouchStart);
      el.removeEventListener("touchmove", handleTouchMove);
    };
  }, [speedFactor]);

  // A re-render (new cards, say) puts fresh panels on the stage at their
  // resting style: bring them to the current progress before they paint.
  useLayoutEffect(() => {
    repaint.current?.();
  });

  return (
    <div
      ref={containerRef}
      className={cn(
        "relative w-full rounded-none sm:rounded-3xl overflow-hidden",
        !containerHeight && "h-[460px] sm:h-[620px] md:h-[650px] lg:h-[710px]",
        "bg-neutral-50 dark:bg-neutral-950 text-neutral-900 dark:text-white",
        "border-0 sm:border border-neutral-200/90 dark:border-neutral-800/80",
        "select-none transition-colors duration-300",
        className
      )}
      style={{
        ...(containerHeight ? { height: containerHeight } : {}),
        ...style,
      }}
      {...props}
    >
      {/* Top Header & Scroll Indicator */}
      <div
        ref={headerRef}
        className="pointer-events-none absolute inset-x-0 top-4 sm:top-5 lg:top-6 z-20 flex flex-col items-center gap-1 sm:gap-1.5 px-3 text-center"
      >
        <div className="flex max-w-full flex-col items-center gap-0.5 sm:gap-1 text-center">
          <p className="text-sm sm:text-base lg:text-lg font-medium tracking-tight text-neutral-900 dark:text-white leading-tight">
            {headerTitle}
          </p>
          <p className="text-[11px] sm:text-xs lg:text-sm text-neutral-500 dark:text-neutral-400 leading-tight">
            {headerSubtitle}
          </p>
        </div>

        {enableScrollIndicator && (
          <div className="flex h-6 sm:h-7 lg:h-8 w-2 shrink-0 flex-col items-center mt-1 sm:mt-1.5 lg:mt-2" aria-hidden="true">
            <div className="size-1.5 sm:size-2 shrink-0 rounded-[2px] border border-neutral-400 dark:border-white/40" />
            <div className="w-px flex-1 bg-gradient-to-b from-neutral-400 dark:from-white/40 to-transparent" />
          </div>
        )}
      </div>

      {/* Presentation Stage: Level, Straight & Top-Calibrated */}
      <div className="relative h-full w-full flex flex-col items-center justify-start overflow-hidden [perspective:1400px] px-3.5 sm:px-6 pt-[106px] sm:pt-[120px] lg:pt-[132px]">
        <div
          ref={stageRef}
          className="flex h-[310px] sm:h-[430px] md:h-[450px] lg:h-[500px] w-full max-w-5xl px-1 sm:px-4 [transform-style:preserve-3d]"
        >
          {cardList.map((card, index) => (
            <Panel
              key={card.title}
              card={card}
              index={index}
              imageSrc={activeImage}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

export default ScrollSplitCards;

/**
 * Motion curves with no animation library behind them.
 *
 * The components here ship as CSS, GSAP or Motion builds that must move
 * identically, so the curves are computed once, from the same numbers, and
 * handed to whichever engine runs them:
 *
 *   - `cubicBezier(x1, y1, x2, y2)` → an easing function (GSAP accepts any
 *     `(progress) => value` as `ease`), exact for Motion's `ease: [..]` arrays
 *     and for CSS `cubic-bezier()`.
 *   - `spring({ stiffness, damping, mass })` → the analytic solution Motion
 *     Motion uses, as an easing function plus the time it takes to settle, or
 *     as a CSS `linear()` string for a fixed start and end.
 *   - `createSpringFollower` → a value that chases a moving target through the
 *     same spring every frame, like Motion's `useSpring`, for pointer-driven
 *     motion that no fixed curve can describe.
 */

// ---------------------------------------------------------------------------
// Cubic bezier
// ---------------------------------------------------------------------------

/**
 * The CSS / Motion cubic-bezier as a function of progress. Newton-Raphson
 * with a bisection fallback, the same solver browsers use.
 */
export function cubicBezier(x1: number, y1: number, x2: number, y2: number) {
  if (x1 === y1 && x2 === y2) return (t: number) => t;

  const a = (p1: number, p2: number) => 1 - 3 * p2 + 3 * p1;
  const b = (p1: number, p2: number) => 3 * p2 - 6 * p1;
  const c = (p1: number) => 3 * p1;
  const at = (t: number, p1: number, p2: number) =>
    ((a(p1, p2) * t + b(p1, p2)) * t + c(p1)) * t;
  const slope = (t: number, p1: number, p2: number) =>
    3 * a(p1, p2) * t * t + 2 * b(p1, p2) * t + c(p1);

  const solveX = (x: number) => {
    let t = x;
    for (let i = 0; i < 8; i++) {
      const s = slope(t, x1, x2);
      if (Math.abs(s) < 1e-6) break;
      const err = at(t, x1, x2) - x;
      if (Math.abs(err) < 1e-7) return t;
      t -= err / s;
    }
    let lo = 0;
    let hi = 1;
    t = x;
    for (let i = 0; i < 30 && hi - lo > 1e-7; i++) {
      const value = at(t, x1, x2);
      if (value < x) lo = t;
      else hi = t;
      t = (lo + hi) / 2;
    }
    return t;
  };

  return (x: number) => (x <= 0 ? 0 : x >= 1 ? 1 : at(solveX(x), y1, y2));
}

/** Motion's named eases, as the cubic-beziers they are. */
export const MOTION_EASE = {
  linear: [0, 0, 1, 1],
  easeIn: [0.42, 0, 1, 1],
  easeOut: [0, 0, 0.58, 1],
  easeInOut: [0.42, 0, 0.58, 1],
  circIn: [0.55, 0, 1, 0.45],
  circOut: [0.55, 0, 0.45, 1],
  circInOut: [0.85, 0, 0.15, 1],
  backIn: [0.31, 0.01, 0.66, -0.59],
  backOut: [0.33, 1.53, 0.69, 0.99],
  anticipate: [0.66, -0.56, 0.34, 1.35],
} as const;

/**
 * Motion's default layout transition (`layout` / `layoutId`):
 * `{ duration: 0.45, ease: [0.4, 0, 0.1, 1] }`.
 */
export const LAYOUT_TRANSITION = { duration: 0.45, ease: [0.4, 0, 0.1, 1] as const };

// ---------------------------------------------------------------------------
// Spring
// ---------------------------------------------------------------------------

export interface SpringOptions {
  /** Motion default 100. */
  stiffness?: number;
  /** Motion default 10. */
  damping?: number;
  /** Motion default 1. */
  mass?: number;
  /** Starting velocity, in units of the whole distance per second. */
  velocity?: number;
  /** How close to the end counts as settled, as a fraction of the distance. */
  restDelta?: number;
}

/**
 * Normalised position (0 → 1) of a spring released from 0 towards 1, at time
 * `t` seconds. The closed-form solution Motion's `spring()` generator
 * uses for the under-, critically and over-damped cases.
 */
export function springAt(options: SpringOptions = {}) {
  const { stiffness = 100, damping = 10, mass = 1, velocity = 0 } = options;
  const zeta = damping / (2 * Math.sqrt(stiffness * mass));
  const omega0 = Math.sqrt(stiffness / mass);
  // Motion's convention: distance still to cover, velocity toward it negated.
  const delta = 1;
  const v0 = -velocity;

  if (zeta < 1) {
    const omegaD = omega0 * Math.sqrt(1 - zeta * zeta);
    return (t: number) => {
      const envelope = Math.exp(-zeta * omega0 * t);
      return (
        1 -
        envelope *
          (((v0 + zeta * omega0 * delta) / omegaD) * Math.sin(omegaD * t) +
            delta * Math.cos(omegaD * t))
      );
    };
  }
  if (zeta === 1) {
    return (t: number) => 1 - Math.exp(-omega0 * t) * (delta + (v0 + omega0 * delta) * t);
  }
  const omegaD = omega0 * Math.sqrt(zeta * zeta - 1);
  return (t: number) => {
    const envelope = Math.exp(-zeta * omega0 * t);
    const freq = Math.min(omegaD * t, 300);
    return (
      1 -
      (envelope *
        ((v0 + zeta * omega0 * delta) * Math.sinh(freq) + omegaD * delta * Math.cosh(freq))) /
        omegaD
    );
  };
}

/** Seconds until the spring stays within `restDelta` of its end. */
export function springDuration(options: SpringOptions = {}) {
  const at = springAt(options);
  const restDelta = options.restDelta ?? 0.001;
  const step = 1 / 240;
  let lastOutside = 0;
  for (let t = 0; t <= 10; t += step) {
    if (Math.abs(1 - at(t)) > restDelta) lastOutside = t;
    else if (t - lastOutside > 0.1) break;
  }
  return Math.max(lastOutside + step, step);
}

/**
 * A spring as a duration and an easing function over it — what GSAP takes:
 *
 *   const { duration, ease } = springEase({ stiffness: 300, damping: 20 });
 *   gsap.to(el, { y: 0, duration, ease });
 *
 * Exact for a fixed start and end; a spring that has to react mid-flight to a
 * new target needs `createSpringFollower` instead.
 */
export function springEase(options: SpringOptions = {}) {
  const duration = springDuration(options);
  const at = springAt(options);
  return {
    duration,
    ease: (progress: number) => (progress >= 1 ? 1 : at(progress * duration)),
  };
}

/**
 * A spring as a CSS `linear()` easing and its duration in ms, for
 * `transition` / `animation` with a fixed start and end.
 *
 *   const { easing, duration } = springLinear({ stiffness: 400, damping: 30 });
 *   el.style.transition = `transform ${duration}ms ${easing}`;
 */
export function springLinear(options: SpringOptions = {}, pointsPerSecond = 60) {
  const duration = springDuration(options);
  const at = springAt(options);
  const count = Math.max(Math.ceil(duration * pointsPerSecond), 8);
  const points: string[] = [];
  for (let i = 0; i <= count; i++) {
    const t = (i / count) * duration;
    points.push(String(Math.round((i === count ? 1 : at(t)) * 10000) / 10000));
  }
  return { easing: `linear(${points.join(", ")})`, duration: Math.round(duration * 1000) };
}

// ---------------------------------------------------------------------------
// Spring follower (useSpring equivalent)
// ---------------------------------------------------------------------------

/** Something that calls back once per frame with the time since the last, in ms. */
export interface FrameTicker {
  add: (callback: (deltaMs: number) => void) => () => void;
}

/** requestAnimationFrame as a ticker — the library-free default. */
export const rafTicker: FrameTicker = {
  add(callback) {
    let last = performance.now();
    let frame = requestAnimationFrame(function tick(now) {
      callback(now - last);
      last = now;
      frame = requestAnimationFrame(tick);
    });
    return () => cancelAnimationFrame(frame);
  },
};

export interface SpringFollower {
  /** Chase a new target from wherever the value is now, keeping its velocity. */
  set: (target: number) => void;
  /** Move to a value instantly, with no motion. */
  jump: (value: number) => void;
  get: () => number;
  destroy: () => void;
}

/**
 * A value that follows its target through a spring, integrating the same
 * equation of motion Motion's `useSpring` solves — so a pointer-driven spring
 * reads the same in every build. Runs only while moving; `onUpdate` receives
 * each new value.
 */
export function createSpringFollower(
  initial: number,
  onUpdate: (value: number) => void,
  options: SpringOptions & { restSpeed?: number; ticker?: FrameTicker } = {},
): SpringFollower {
  const { stiffness = 100, damping = 10, mass = 1, ticker = rafTicker } = options;
  const restDelta = options.restDelta ?? 0.01;
  const restSpeed = options.restSpeed ?? 0.01;
  let value = initial;
  let target = initial;
  let velocity = 0;
  let stop: (() => void) | null = null;

  const step = (deltaMs: number) => {
    // Fixed 1ms sub-steps keep the integration stable for stiff springs and
    // independent of the frame rate.
    const steps = Math.min(Math.max(Math.round(deltaMs), 1), 250);
    for (let i = 0; i < steps; i++) {
      const force = -stiffness * (value - target) - damping * velocity;
      velocity += (force / mass) * 0.001;
      value += velocity * 0.001;
    }
    if (Math.abs(target - value) < restDelta && Math.abs(velocity) < restSpeed) {
      value = target;
      velocity = 0;
      stop?.();
      stop = null;
    }
    onUpdate(value);
  };

  return {
    set(next) {
      target = next;
      if (!stop && value !== target) stop = ticker.add(step);
    },
    jump(next) {
      stop?.();
      stop = null;
      value = target = next;
      velocity = 0;
      onUpdate(value);
    },
    get: () => value,
    destroy() {
      stop?.();
      stop = null;
    },
  };
}
